  vec2 uv3 = uv * vec2(40.0, 200.0);
  float n2 = hash12(
    floor(uv3 + vec2(t * 3.0, t * 20.0))
  );
  streak += smoothstep(0.92, 1.0, n2) * 0.5;
  vec3 rainC = vec3(0.75, 0.8, 0.9);
