    #endif
  }
  if (chromaticIntensity > 0.001) {
    #if USE_TEXTURE
      col.rgb = applyChromaticAberration(
        uv, cc_spriteTexture
      );
    #endif
  }
  if (radialBlurIntensity > 0.001) {
    #if USE_TEXTURE
      col.rgb = applyRadialBlur(
        uv, cc_spriteTexture
      );
    #endif
