      || abs(saturation - 1.0) > 0.001
      || abs(colorTemp) > 0.001) {
    col.rgb = applyColorGrading(col.rgb);
  }
  if (grayscaleWeight > 0.001) {
    col.rgb = applyGrayscale(col.rgb);
  }
  if (abs(splitShadowR - 0.5) > 0.01
      || abs(splitShadowG - 0.5) > 0.01
      || abs(splitShadowB - 0.5) > 0.01
      || abs(splitHighlightR - 0.5) > 0.01
      || abs(splitHighlightG - 0.5) > 0.01
      || abs(splitHighlightB - 0.5) > 0.01) {
    col.rgb = applySplitToning(col.rgb);
  }
