    col.rgb = applyFilmGrain(col.rgb, uv);
  }
  if (sandstormIntensity > 0.001) {
    col.rgb = applySandstorm(col.rgb, uv);
  }
  if (fogDensity > 0.001) {
    col.rgb = applyWeatherFog(col.rgb, uv);
  }
  if (rainWetness > 0.001) {
    col.rgb = applyRainWetness(col.rgb);
  }
  if (rainScreenIntensity > 0.001) {
    col.rgb = applyRainScreen(col.rgb, uv);
  }
  if (snowScreenIntensity > 0.001
      || snowBrightness > 0.001
      || snowFrostEdge > 0.001) {
    col.rgb = applySnowScreen(col.rgb, uv);
  }
  if (vignetteIntensity > 0.001) {
    col.rgb *= applyVignette(uv);
  }
  col *= v_color;
  col.rgb = clamp(col.rgb, 0.0, 1.0);
  return col;
}
