float flakeDistance(vec3 p, float t) {
  const float snowMax = 20.0;
  if (abs(p.x) > snowMax
      || abs(p.y) > snowMax
      || abs(p.z) > snowMax) {
    return 9999.9;
  }
  float sp = 1.25 * t;
  p.x += sp * -10.0;
  p.y += sp * 1.5;
  p.z += sp * -0.25;
  const float md = 4.0;
  float stepX = floor(p.x / md);
  float stepY = floor(p.y / md);
  float stepZ = floor(p.z / md);
  vec3 fp = vec3(
    mod(p.x, md), mod(p.y, md), mod(p.z, md)
  );
  vec3 fpos = vec3(md * 0.5);
  fpos.x += sin(sp + stepY) * (2.0 / 5.0) * md;
  fpos.y += sin(sp + stepZ * 1.3) * (2.0 / 5.0) * md;
  fpos.z += sin(sp + stepX * 1.7) * (2.0 / 5.0) * md;
